functions.switchTab:
function switchTab(e, tabId) {
        document.querySelectorAll('.tab-content').forEach(el => el.classList.remove('active'));
        document.querySelectorAll('.tab-btn').forEach(el => { 
            el.classList.remove('active', 'border-blue-600', 'text-blue-600'); 
            el.classList.add('text-slate-500'); 
        });
        document.getElementById(tabId).classList.add('active');
        e.currentTarget.classList.remove('text-slate-500'); 
        e.currentTarget.classList.add('active', 'border-blue-600', 'text-blue-600');

        // 徹底修復 hidden 畫布無寬高像素之 Chart.js 原生缺陷
        if (tabId === 'financials') {
            if (window.charts.orclSegment) window.charts.orclSegment.resize();
            if (window.charts.orclProfit) window.charts.orclProfit.resize();
        } else if (tabId === 'valuation') {
            if (window.charts.orclValuation) window.charts.orclValuation.resize();
        }
    }

functions.callGeminiAPI:
async function callGeminiAPI(prompt, systemInstruction) {
        try {
            const response = await fetch('/api/gemini', {
                method: 'POST', headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ prompt: prompt, systemInstruction: systemInstruction })
            });
            const data = await response.json();
            if (!response.ok) return `連線錯誤：${data.error || '未知錯誤'}`;
            let rawText = data.candidates?.[0]?.content?.parts?.[0]?.text || "抱歉，無法產生有效回覆。";
            return rawText.replace(/\n/g, '<br>').replace(/\*\*(.*?)\*\*/g, '<b>$1</b>');
        } catch (error) { return `網路連線失敗。(${error.message})`; }
    }

functions.appendMessage:
function appendMessage(text, isUser) {
        const msgDiv = document.createElement('div');
        msgDiv.className = isUser ? 'bg-blue-100 text-blue-900 rounded-tr-none rounded-2xl ml-auto max-w-[85%] p-3 text-sm shadow-sm' : 'bg-white border border-slate-200 text-slate-700 rounded-tl-none rounded-2xl mr-auto max-w-[85%] p-3 text-sm shadow-sm leading-relaxed';
        msgDiv.innerHTML = text; document.getElementById('chat-messages').appendChild(msgDiv);
        document.getElementById('chat-messages').scrollTop = document.getElementById('chat-messages').scrollHeight;
    }

functions.showTypingIndicator:
function showTypingIndicator() {
        const ind = document.createElement('div'); ind.id = `typing-indicator-${Date.now()}`;
        ind.className = 'bg-slate-200 text-slate-500 rounded-tl-none rounded-2xl mr-auto max-w-[85%] p-3 text-sm shadow-sm flex gap-1 items-center h-10';
        ind.innerHTML = '<div class="w-2 h-2 bg-slate-400 rounded-full typing-dot"></div><div class="w-2 h-2 bg-slate-400 rounded-full typing-dot"></div><div class="w-2 h-2 bg-slate-400 rounded-full typing-dot"></div>';
        document.getElementById('chat-messages').appendChild(ind);
        return ind.id;
    }

functions.handleChatSubmit:
async function handleChatSubmit(e) {
        e.preventDefault(); const input = document.getElementById('chat-input'); const text = input.value.trim(); if (!text) return;
        const sendBtn = e.target.querySelector('button[type="submit"]'); if (sendBtn && sendBtn.disabled) return;
        if (sendBtn) { sendBtn.disabled = true; sendBtn.classList.add('opacity-50', 'cursor-not-allowed'); }
        input.value = ''; appendMessage(text, true); const typingId = showTypingIndicator();
        try {
            const res = await callGeminiAPI(text, standardPrompt);
            document.getElementById(typingId)?.remove(); appendMessage(res, false);
        } finally {
            document.getElementById(typingId)?.remove();
            if (sendBtn) { sendBtn.disabled = false; sendBtn.classList.remove('opacity-50', 'cursor-not-allowed'); }
        }
    }

